import io, json, collections
BASE = 'app/src/main/assets/substances/'
R = ['name','commonNames','url','isApproved','tolerance','crossTolerances','addictionPotential','toxicities','effectsSummary','dosageRemark','generalRisks','longtermRisks','saferUse','interactions','metabolism','metabolismSources','categories','summary','roas']
Z = ['tolerance','addictionPotential','toxicities','effectsSummary','dosageRemark','generalRisks','longtermRisks','saferUse','interactions','metabolism','metabolismSources','summary','localizedName']
def load(path): return json.load(io.open(path, encoding='utf-8-sig'), object_pairs_hook=collections.OrderedDict)
def save(path, d, keys):
    out=collections.OrderedDict((k,d[k]) for k in keys if k in d)
    out.update((k,v) for k,v in d.items() if k not in out)
    io.open(path,'w',encoding='utf-8',newline='\r\n').write(json.dumps(out,ensure_ascii=False,indent=2))
def update_both(name, root_fields, zh_fields):
    rp=BASE+'root/'+name+'.json'; zp=BASE+'zh_cn/'+name+'.json'
    r=load(rp); z=load(zp); r.update(root_fields); z.update(zh_fields); z['roas']=r['roas']
    save(rp,r,R); save(zp,z,Z)
# LSA seed tables are not standard pure-LSA doses; remove the unsupported sublingual route.
r=load(BASE+'root/LSA.json'); r['roas']=[{'name':'oral'}]
r['dosageRemark']="FreeODwiki's seed tables are not standardized LSA doses: morning glory seeds are listed as threshold 20-50 seeds/1.5 g, light 50-100 seeds/1.5-3 g, moderate 100-250 seeds/3-6 g, strong 250-400 seeds/6-10 g, heavy 400+/10 g+; Hawaiian baby woodrose seeds are separately listed as threshold 1-3, light 3-5, moderate 5-7, strong 7-12, heavy 12+ seeds. The page gives no standardized pure-LSA oral or sublingual dose, so no numeric route dose is encoded. Educational user/resource information, not a recommendation."
r['effectsSummary']="FreeODwiki says reported LSA experiences are often sedating/dreamlike, with mild-to-moderate and inconsistent psychedelic effects, prominent physical/cognitive effects and sometimes severe nausea. It cautions seed experiences may involve multiple alkaloids, not LSA alone."
r['generalRisks']="The source reports nausea, bodily discomfort, strong vasoconstriction and variable blood-pressure effects; seed experiences may reflect mixtures of alkaloids rather than LSA alone. Severe anxiety, paranoia or psychosis may occur, especially with predisposition."
r['saferUse']=["FreeODwiki recommends starting low because seed alkaloid content and individual sensitivity vary, and recommends harm reduction.","Seed counts are not standardized pure-LSA doses; the page gives no sublingual dose table."]
save(BASE+'root/LSA.json',r,R);z=load(BASE+'zh_cn/LSA.json');z['roas']=r['roas']
z['dosageRemark']="FreeODwiki 的种子剂量表不是标准化 LSA 剂量：牵牛花种子列为阈值 20-50 颗/1.5 g、轻微 50-100 颗/1.5-3 g、中等 100-250 颗/3-6 g、强烈 250-400 颗/6-10 g、严重 400 颗以上/10 g 以上；夏威夷小木玫瑰种子另列为阈值 1-3 颗、轻微 3-5 颗、中等 5-7 颗、强烈 7-12 颗、严重 12 颗以上。页面没有标准化纯 LSA 口服或舌下剂量，因此不将数值写入路线剂量字段。用户/资源教育资料，不是建议。"
z['effectsSummary']="FreeODwiki 称用户报告中的 LSA 体验常呈镇静、梦幻感，致幻效应轻至中等且不稳定，躯体/认知效应突出，并可能伴严重恶心。来源提醒种子体验可能由多种生物碱共同产生，而非仅由 LSA 产生。"
z['generalRisks']="来源报告恶心、身体不适、明显血管收缩及血压变化；种子体验可能来自多种生物碱混合物。心理不良反应包括严重焦虑、偏执或精神病发作，具有相关倾向者尤其需谨慎。"
z['saferUse']=["FreeODwiki 建议考虑种子生物碱含量和个体敏感性、从低处开始，并采取伤害减少措施。","种子颗数不是标准化纯 LSA 剂量；页面没有舌下剂量表。"]
save(BASE+'zh_cn/LSA.json',z,Z)
# mCPP: threshold is 15 mg; light band starts at 20 mg. Preserve stub warning.
