# Apply light-band lower bounds separately from each source threshold.
for name, lower in [('MCPP',20),('ΑMT',10),('Βk-2C-B',60)]:
    rp=BASE+'root/'+name+'.json'; zp=BASE+'zh_cn/'+name+'.json'
    r=load(rp); r['roas'][0]['dose']['lightMin']=lower; save(rp,r,R)
    z=load(zp); z['roas']=r['roas']; save(zp,z,Z)
print('LSA MCPP ΑMT Βk-2C-B updated')